"""Write src/shoot-sizes.js: the size of every image in public/assets/shoot/.
Run after scripts/escape-media.py."""
import os
from PIL import Image
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
D = os.path.join(ROOT, 'public', 'assets', 'shoot')
rows = []
for f in sorted(os.listdir(D)):
    if f.endswith('.webp'):
        w, h = Image.open(os.path.join(D, f)).size
        rows.append(f"  '{f[:-5]}': [{w}, {h}],")
open(os.path.join(ROOT, 'src', 'shoot-sizes.js'), 'w').write(
    '// Generated by scripts/shoot-sizes.py: [width, height] of each image in public/assets/shoot/.\n'
    'export default {\n' + '\n'.join(rows) + '\n}\n')
print(len(rows), 'images')
